  dna: ['BIO:14', 'BIO:15', 'COB:9', 'MIC:10', 'ORG:28'], cell: ['BIO:4', 'BIO:5', 'BIO:7', 'BIO:8', 'COB:3', 'MIC:3'],
  life: ['BIO:1', 'BIO:33', 'BIO:29', 'BIO:30', 'BIO:44', 'COB:16'], earth: ['AST:8', 'AST:4', 'AST:9', 'UP2:11'],
